#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
Battery Monitor for Raspberry Pi using ADS1115.

This script continuously reads the battery voltage via an ADS1115 Analog-to-Digital Converter
and displays the charge percentage.
"""

import time
import smbus2
from functools import partial

# Constants
I2C_BUS = 1
ADS1115_ADDRESS = 0x48
ADS1115_CONFIG_REGISTER = 0x01
ADS1115_CONVERSION_REGISTER = 0x00
FULL_SCALE_VOLTAGE = 6.0  # ADS1115 voltage range
VOLTAGE_DIVIDER_RATIO = 25  # Voltage divider ratio (R1 + R2)/R2
CONVERSION_TIME = 0.01  # Conversion time in seconds


def initialize_i2c_bus(bus_number: int) -> smbus2.SMBus:
    """Initializes and returns the I2C bus."""
    try:
        return smbus2.SMBus(bus_number)
    except Exception as e:
        raise IOError(f"Failed to initialize I2C bus: {e}")


def configure_ads1115(bus: smbus2.SMBus, address: int) -> None:
    """Configures the ADS1115 for single-shot conversion on channel 0."""
    config_values = [0x83, 0xE0]  # Single-shot, A0, Disable comparator
    try:
        bus.write_i2c_block_data(address, ADS1115_CONFIG_REGISTER, config_values)
    except Exception as e:
        raise IOError(f"Failed to configure ADS1115: {e}")


def trigger_conversion(bus: smbus2.SMBus, address: int) -> None:
    """Triggers a new ADS1115 conversion."""
    try:
        bus.write_byte_data(address, ADS1115_CONFIG_REGISTER, 0x85)  # Start single conversion
    except Exception as e:
        raise IOError(f"Failed to trigger conversion: {e}")


def read_conversion_result(bus: smbus2.SMBus, address: int) -> int:
    """Reads the conversion result from the ADS1115."""
    try:
        data = bus.read_i2c_block_data(address, ADS1115_CONVERSION_REGISTER, 2)
        result = (data[0] << 8) | data[1]
        if result > 32767:
            result -= 65536
        return result
    except Exception as e:
        raise IOError(f"Failed to read conversion result: {e}")


def calculate_battery_voltage(raw_value: int) -> float:
    """Converts the raw ADS1115 value to battery voltage."""
    return (raw_value * FULL_SCALE_VOLTAGE) / 32767


def calculate_charge_percentage(battery_voltage: float) -> float:
    """Calculates the battery charge percentage based on voltage."""
    if battery_voltage > 4.05:
        percentage = ((battery_voltage - 4.05) / (5.0 - 4.05)) * 100
        return max(0.0, min(100.0, percentage))  # Ensure percentage is within 0-100%
    else:
        return 0.0


def main():
    """Main function to continuously monitor battery charge."""

    try:
        bus = initialize_i2c_bus(I2C_BUS)
        configure_ads1115(bus, ADS1115_ADDRESS)
    except IOError as e:
        print(f"Initialization error: {e}")
        return

    last_percentage = None

    try:
        while True:
            trigger_conversion(bus, ADS1115_ADDRESS)
            time.sleep(CONVERSION_TIME)

            try:
                raw_value = read_conversion_result(bus, ADS1115_ADDRESS)
                battery_voltage = calculate_battery_voltage(raw_value) * (1.0 / VOLTAGE_DIVIDER_RATIO)
                charge_percentage = calculate_charge_percentage(battery_voltage)

                if charge_percentage != last_percentage:
                    print(f"Battery Voltage: {battery_voltage:.2f} V | Charge: {charge_percentage:.2f}%")
                    last_percentage = charge_percentage

            except IOError as read_error:
                print(f"Error reading from ADS1115: {read_error}")
                continue

            time.sleep(1)

    except KeyboardInterrupt:
        print("\nExiting")

    finally:
        if 'bus' in locals():
            bus.close()
            print("I2C bus closed.")


if __name__ == "__main__":
    main()

