#!/usr/bin/env python3
# ADC Demo for Raspberry Pi using I2C ADS1115
# Hobbyist Project

import time
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Constants
I2C_BUS = 1  # I2C bus number
ADC_GAIN = 1  # Gain setting for the ADC
READ_INTERVAL = 0.5  # Time between readings in seconds

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_adc(i2c_bus):
    """Initializes the ADS1115 ADC."""
    try:
        adc = ADS.ADS1115(i2c_bus)
        adc.gain = ADC_GAIN
        return adc
    except Exception as e:
        print(f"Error initializing ADS1115: {e}")
        return None

def create_channels(adc):
    """Creates analog input channels on the ADC."""
    return [AnalogIn(adc, i) for i in range(4)]

def read_channels(channels):
    """Reads values from all channels."""
    return [channel.value for channel in channels]

def format_output(values):
    """Formats the channel values for output."""
    return '| {0:>6} | {1:>6} | {2:>6} | {3:>6} |'.format(*values)

def print_header():
    """Prints the header for the output table."""
    print('Reading ADS1115 values')
    print(format_output(['A0', 'A1', 'A2', 'A3']))
    print('-' * 37)

def main():
    """Main function to continuously read and display ADC values."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    adc = initialize_adc(i2c_bus)
    if adc is None:
        return

    channels = create_channels(adc)

    try:
        print_header()
        while True:
            values = read_channels(channels)
            print(format_output([f"{val:05}" for val in values]))
            time.sleep(READ_INTERVAL)
    except KeyboardInterrupt:
        print("\nExiting...")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        print("Program finished.")

if __name__ == "__main__":
    main()

