#!/usr/bin/env python3

import time
import logging
import cv2
from picamera2 import Picamera2
from pyzbar.pyzbar import decode

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def initialize_camera():
    """Initializes the Raspberry Pi camera."""
    try:
        camera = Picamera2()
        camera.configure(camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)}))
        camera.start()
        logging.info("Camera initialized successfully.")
        return camera
    except Exception as e:
        logging.error(f"Error initializing camera: {e}")
        return None

def capture_frame(camera):
    """Captures a single frame from the camera."""
    try:
        frame = camera.capture_array()
        logging.debug("Frame captured.")
        return frame
    except Exception as e:
        logging.error(f"Error capturing frame: {e}")
        return None

def decode_qr_code(frame):
    """Decodes QR codes in a frame."""
    try:
        gray_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        decoded_objects = decode(gray_frame)
        return decoded_objects
    except Exception as e:
        logging.error(f"Error decoding QR code: {e}")
        return []

def process_frame(camera):
    """Captures a frame, decodes QR codes, and prints a message if a code is found."""
    frame = capture_frame(camera)
    if frame is None:
        return

    decoded_objects = decode_qr_code(frame)

    if decoded_objects:
        logging.info("QR code detected.")
        print("Hello, World!")  # Print a message if a QR code is detected
    else:
        logging.info("No QR code detected.")

def main():
    """Main function to run the QR code scanner."""
    camera = initialize_camera()
    if camera is None:
        return

    try:
        while True:
            process_frame(camera)
            time.sleep(1)  # Check for QR codes every 1 second
    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    finally:
        camera.stop()
        logging.info("Camera stopped.")

if __name__ == "__main__":
    main()

