import time
import cv2
import numpy as np

# Configuration constants
CAMERA_INDEX = 0
FRAMERATE = 15
WARMUP_DELAY = 2
MOTION_THRESHOLD = 10
IMAGE_FILENAME = "motion.jpg"

def initialize_camera(camera_index, framerate):
    """Initializes the camera with specified parameters."""
    try:
        cap = cv2.VideoCapture(camera_index)
        if not cap.isOpened():
            raise IOError("Cannot open webcam")
        cap.set(cv2.CAP_PROP_FRAME_WIDTH, 640)  # Example width
        cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 480) # Example height
        cap.set(cv2.CAP_PROP_FPS, framerate)
        return cap
    except Exception as e:
        print(f"Camera initialization error: {e}")
        return None

def capture_frame(cap):
    """Captures a single frame from the camera."""
    try:
        ret, frame = cap.read()
        if not ret:
            print("Failed to capture frame")
            return None
        return frame
    except Exception as e:
        print(f"Frame capture error: {e}")
        return None

def detect_motion(current_frame, baseline_average, threshold):
    """Detects motion by comparing current frame average to baseline."""
    try:
        current_average = float(np.mean(current_frame))
        if abs(current_average - baseline_average) > threshold:
            return True, current_average
        return False, current_average
    except Exception as e:
        print(f"Motion detection error: {e}")
        return False, baseline_average

def save_image(frame, filename):
    """Saves the current frame to a file."""
    try:
        cv2.imwrite(filename, frame)
        print(f"Motion detected! Image saved to {filename}")
    except Exception as e:
        print(f"Image saving error: {e}")

def main():
    """Main function to run the motion detection loop."""
    cap = initialize_camera(CAMERA_INDEX, FRAMERATE)
    if cap is None:
        return

    print('Starting motion detection...')
    time.sleep(WARMUP_DELAY)

    baseline_average = float(np.mean(capture_frame(cap))) # Capture initial frame for baseline

    try:
        while True:
            frame = capture_frame(cap)
            if frame is None:
                break

            motion_detected, new_average = detect_motion(frame, baseline_average, MOTION_THRESHOLD)

            if motion_detected:
                save_image(frame, IMAGE_FILENAME)
                baseline_average = new_average # Update baseline after saving the image

            time.sleep(2) # Pause between captures

    except KeyboardInterrupt:
        print('Script interrupted. Exiting...')
    finally:
        cap.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

