import RPi.GPIO as GPIO
import time
import datetime
import argparse
import csv
import io
from picamera2 import Picamera2
import os

def parse_arguments():
    """Parses command-line arguments."""
    parser = argparse.ArgumentParser(description="Vibration monitoring system for hydroponics control.")
    parser.add_argument("-g", "--gpio", required=True, help="Comma-separated list of GPIO pin numbers (BCM numbering) for the vibration sensors.")
    parser.add_argument("-l", "--log_file", required=True, help="Path to the CSV log file.")
    parser.add_argument("-i", "--interval", type=float, default=0.1, help="Sampling interval in seconds.")
    parser.add_argument("-c", "--calibrate", type=int, default=60, help="Calibration duration in seconds.")
    parser.add_argument("-p", "--picture_interval", type=int, default=300, help="Picture capture interval in seconds.")
    return parser.parse_args()

def setup_gpio(gpio_pins):
    """Sets up the GPIO pins for the vibration sensors."""
    try:
        GPIO.setmode(GPIO.BCM)
        for pin in gpio_pins:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)  # Use pull-down resistors
            print(f"GPIO pin {pin} set up as input with pull-down resistor.")
    except Exception as e:
        print(f"Error setting up GPIO pins: {e}")
        return False
    return True

def calibrate_sensors(gpio_pins, calibration_duration):
    """Calibrates the vibration sensors and returns baseline thresholds."""
    print("Calibrating sensors...")
    baseline_counts = {pin: 0 for pin in gpio_pins}
    start_time = time.time()
    while time.time() - start_time < calibration_duration:
        for pin in gpio_pins:
            if GPIO.input(pin) == GPIO.HIGH:
                baseline_counts[pin] += 1
        time.sleep(0.01)  # Small delay to avoid overwhelming the sensors

    thresholds = {}
    for pin, count in baseline_counts.items():
        percentage = (count / (calibration_duration * 0.01)) * 100  # Calculate percentage of HIGH readings
        threshold = percentage * 1.2  # Add 20% to the baseline
        thresholds[pin] = threshold
        print(f"Sensor on GPIO {pin}: Baseline percentage = {percentage:.2f}%, Threshold = {threshold:.2f}%")
    return thresholds

def monitor_sensors(gpio_pins, thresholds, sampling_interval):
    """Monitors the vibration sensors and returns the sensor states."""
    sensor_states = {pin: 0 for pin in gpio_pins}
    high_counts = {pin: 0 for pin in gpio_pins}
    start_time = time.time()
    while time.time() - start_time < sampling_interval:
        for pin in gpio_pins:
            if GPIO.input(pin) == GPIO.HIGH:
                high_counts[pin] += 1
        time.sleep(0.01)

    for pin in gpio_pins:
        percentage = (high_counts[pin] / (sampling_interval * 0.01)) * 100
        if percentage > thresholds[pin]:
            sensor_states[pin] = 1
        else:
            sensor_states[pin] = 0
    return sensor_states

def capture_image(picam2):
    """Captures an image using the CSI camera module."""
    try:
        timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
        image_path = os.path.join("images", f"{timestamp}.jpg")
        picam2.capture_file(image_path)
        print(f"Image captured: {image_path}")
    except Exception as e:
        print(f"Error capturing image: {e}")

def main():
    """Main function to run the vibration monitoring system."""
    args = parse_arguments()

    gpio_pins = [int(pin) for pin in args.gpio.split(",")]
    sampling_interval = args.interval
    calibration_duration = args.calibrate
    picture_interval = args.picture_interval
    log_file_path = args.log_file

    if not setup_gpio(gpio_pins):
        print("GPIO setup failed. Exiting.")
        return

