import config
import face
import hardware

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Global variables
model = None
camera = None
lock = None
button = None
audio = None

def load_model():
    """Loads the face recognition model."""
    global model
    try:
        model_path = config.TRAINING_FILE
        if not model_path.exists():
            raise FileNotFoundError(f"Training file not found: {model_path}")
        model = cv2.face.EigenFaceRecognizer_create()
        model.read(str(model_path))  # OpenCV expects strings
        logger.info("Face recognition model loaded successfully.")
    except Exception as e:
        logger.error(f"Error loading face recognition model: {e}")
        sys.exit(1)


def initialize_hardware():
    """Initializes the camera, door lock, button, and audio system."""
    global camera, lock, button, audio
    try:
        camera = config.get_camera()
        lock = hardware.DoorLock()
        button = hardware.Button()
        audio = hardware.Audio()

        logger.info("Hardware initialized successfully.")
    except Exception as e:
        logger.error(f"Error initializing hardware: {e}")
        sys.exit(1)


def process_face(frame):
    """Processes a single frame to detect and recognize a face."""
    try:
        gray_frame = cv2.cvtColor(frame, cv2.COLOR_RGB2GRAY)
        face_coords = face.detect_single(gray_frame)

        if face_coords is None:
            logger.warning("Could not detect a single face.")
            return False

        x, y, w, h = face_coords
        cropped_face = face.crop(gray_frame, x, y, w, h)
        resized_face = face.resize(cropped_face)

        label, confidence = model.predict(resized_face)

        logger.info(f"Predicted {'POSITIVE' if label == config.POSITIVE_LABEL else 'NEGATIVE'} face with confidence {confidence}")

        if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
            logger.info("Recognized face! Unlocking door...")
            unlock_door()
            audio.play(config.WELCOME_SOUND, config.AUDIO_CHANNEL_0)
            return True
        else:
            logger.warning("Face not recognized.")
            audio.play(config.WAIT_SOUND, config.AUDIO_CHANNEL_1)
            audio.play(config.LATER_SOUND, config.AUDIO_CHANNEL_2)
            return False

    except Exception as e:
        logger.error(f"Error processing face: {e}")
        return False



def manual_lock():
    """Manually locks the door."""
    try:
        if lock.is_locked:
            logger.info("Door is already locked.")
        else:
            lock.lock()
            logger.info("Door manually locked.")
    except Exception as e:
        logger.error(f"Error manually locking the door: {e}")



def unlock_door():
    """Unlocks the door."""
    try:
        if not lock.is_locked:
            lock.unlock()
            logger.info("Door unlocked.")
    except Exception as e:
        logger.error(f"Error unlocking the door: {e}")


def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    logger.info("Received signal, exiting gracefully...")
    sys.exit(0)


def is_input_available(timeout=0.0):
    """Checks if there is input available on stdin."""
    rlist, _, _ = select.select([sys.stdin], [], [], timeout)
    return bool(rlist)


def read_input():
    """Reads a single character from stdin without blocking."""
    if is_input_available():
        return sys.stdin.read(1).lower()
    return None


def main():
    """Main function to run the face recognition and door control."""
    global camera, lock

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    load_model()
    initialize_hardware()

    try:
        while True:
            if button.is_pressed:
                logger.info("Button pressed, processing face...")
                frame = camera.read()
                if frame is not None:
                    process_face(frame)
                else:
                    logger.error("Failed to read frame from camera.")
                time.sleep(config.BUTTON_DEBOUNCE_DELAY)

            if read_input() == 'l':
                manual_lock()

            time.sleep(0.1)  # Reduce CPU usage

    except KeyboardInterrupt:
        logger.info("Exiting program.")
    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        logger.info("Releasing resources and cleaning up...")
        if camera:
            camera.release()
        if lock:
            lock.cleanup()
        if button:
            button.cleanup()
        if audio:
            audio.stop()
            audio.quit()


if __name__ == "__main__":
    main()

