import cv2
import select
import sys
import time
import logging
import config
import face
import hardware

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class Sound:
    """Represents a sound file with pre-loaded audio and metadata."""

    def __init__(self, description, filename):
        self.description = description
        try:
            self.audio = config.audio_player.load(filename)
            self.metadata = config.audio_player.get_metadata(filename)
        except Exception as e:
            logger.error(f"Error loading sound file {filename}: {e}")
            self.audio = None
            self.metadata = None

    def play(self):
        """Plays the loaded sound."""
        if self.audio:
            try:
                config.audio_player.play(self.audio)
            except Exception as e:
                logger.error(f"Error playing sound: {e}")


def is_input_available(timeout=0.0):
    """Checks for input availability on stdin."""
    rlist, _, _ = select.select([sys.stdin], [], [], timeout)
    return bool(rlist)


def read_input():
    """Reads a single character from stdin (non-blocking)."""
    if is_input_available():
        return sys.stdin.read(1).lower()
    return None


def process_face_recognition():
    """Performs face recognition and controls the door lock."""

    def recognize_face():
        """Tries to recognize a face in the captured image."""
        try:
            image = config.camera.read()
            gray_image = cv2.cvtColor(image, cv2.COLOR_RGB2GRAY)
            face_coords = face.detect_single(gray_image)
            if face_coords is None:
                return None, None
            x, y, w, h = face_coords
            cropped_face = face.crop(gray_image, x, y, w, h)
            resized_face = face.resize(cropped_face)
            label, confidence = config.model.predict(resized_face)
            return label, confidence
        except Exception as e:
            logger.error(f"Error during face recognition: {e}")
            return None, None


    def handle_recognition_result(label, confidence):
        """Handles the face recognition result and triggers corresponding actions."""
        if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
            logger.info("Recognized face! Unlocking Door...")
            config.door.unlock()
            welcome_sound.play()
            return True
        else:
            logger.warning("Face not recognized!")
            wait_sound.play()
            return False

    def handle_no_face():
        """Handles the case where no face is detected in the image."""
        logger.warning("No face detected!")
        later_sound.play()

    # Sound definitions
    global welcome_sound, wait_sound, later_sound
    welcome_sound = Sound("welcome", "sounds/welcome.wav")
    wait_sound = Sound("wait", "sounds/wait.wav")
    later_sound = Sound("later", "sounds/later.wav")

    logger.info("Face Recognition Starting...")

