import cv2
import numpy as np
from typing import Tuple, List

def initialize_camera(width: int = 640, height: int = 480) -> cv2.VideoCapture:
    """Initializes the camera with specified width and height."""
    try:
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            raise IOError("Cannot open webcam")
        camera.set(cv2.CAP_PROP_FRAME_WIDTH, width)
        camera.set(cv2.CAP_PROP_FRAME_HEIGHT, height)
        return camera
    except IOError as e:
        print(f"Error initializing camera: {e}")
        return None

def load_cascade_classifier(cascade_path: str) -> cv2.CascadeClassifier:
    """Loads the Haar Cascade Classifier from the specified path."""
    try:
        classifier = cv2.CascadeClassifier(cv2.data.haarcascades + cascade_path)
        if classifier.empty():
            raise ValueError(f"Cannot load cascade classifier from {cascade_path}")
        return classifier
    except ValueError as e:
        print(f"Error loading cascade classifier: {e}")
        return None

def detect_faces(image: np.ndarray, classifier: cv2.CascadeClassifier) -> List[Tuple[int, int, int, int]]:
    """Detects faces in the given image using the provided classifier."""
    gray_image = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    faces = classifier.detectMultiScale(gray_image, scaleFactor=1.3, minNeighbors=5)
    return faces

def draw_rectangles(image: np.ndarray, faces: List[Tuple[int, int, int, int]]) -> None:
    """Draws rectangles around the detected faces in the image."""
    for (x, y, w, h) in faces:
        cv2.rectangle(image, (x, y), (x + w, y + h), (0, 255, 0), 2)

def display_frame(window_name: str, frame: np.ndarray) -> None:
    """Displays the given frame in a window."""
    cv2.imshow(window_name, frame)

def process_frame(camera: cv2.VideoCapture, window_name: str, classifier: cv2.CascadeClassifier) -> bool:
    """Captures a frame, detects faces, and displays the result."""
    ret, frame = camera.read()
    if not ret:
        print("Failed to grab frame")
        return False

    faces = detect_faces(frame, classifier)
    draw_rectangles(frame, faces)
    display_frame(window_name, frame)

    return True

def main() -> None:
    """Main function to run the face detection."""
    window_name = "Face Detection"
    cascade_path = "haarcascade_frontalface_default.xml"

    camera = initialize_camera()
    if camera is None:
        return

    classifier = load_cascade_classifier(cascade_path)
    if classifier is None:
        camera.release()
        return

    try:
        while True:
            if cv2.getWindowProperty(window_name, cv2.WND_PROP_AUTOSIZED) == 1:
                if not process_frame(camera, window_name, classifier):
                    break
            else:
                print("Window is not resized, skipping frame.")

            key = cv2.waitKey(1) & 0xFF
            if key == ord("q") or key == 27:  # 'q' or ESC key
                print("Exiting...")
                break
    finally:
        camera.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

