import time
import subprocess
import os

# Constants
SLEEP_INTERVAL_SECONDS = 5


def get_cpu_temperature():
    """Reads the CPU temperature from the system.

    Returns:
        float: The CPU temperature in Celsius, or None if an error occurs.
    """
    try:
        output = subprocess.check_output(['vcgencmd', 'measure_temp'], text=True).strip()
        temperature_str = output.split('=')[1]
        return float(temperature_str.split('\'')[0])
    except (subprocess.CalledProcessError, IndexError, ValueError) as e:
        print(f"Error reading CPU temperature: {e}")
        return None


def print_cpu_temperature(temperature):
    """Prints the CPU temperature to the console.

    Args:
        temperature (float): The CPU temperature in Celsius.
    """
    if temperature is not None:
        print(f"CPU Temperature: {temperature:.2f}°C")


def main():
    """Main function to continuously monitor and print the CPU temperature."""
    try:
        while True:
            temperature = get_cpu_temperature()
            print_cpu_temperature(temperature)
            time.sleep(SLEEP_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")


if __name__ == "__main__":
    main()

