#!/usr/bin/env python3
# altitude_monitor.py
# Reads altitude from a BMP280 sensor and displays relative altitude.
# Target: Raspberry Pi 3 Model B+

import time
import board
import busio
import adafruit_bmp280

# Constants
I2C_BUS = 1  # I2C bus number
SDA_PIN = 2  # SDA pin number
SCL_PIN = 3  # SCL pin number
BASELINE_READING_COUNT = 10  # Number of baseline readings
BASELINE_READING_INTERVAL = 1  # Interval between baseline readings (seconds)
ALTITUDE_READING_INTERVAL = 1  # Interval between altitude readings (seconds)


def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except ValueError as e:
        print(f"Error initializing I2C: {e}")
        return None


def initialize_bmp280(i2c_bus):
    """Initializes the BMP280 sensor."""
    try:
        return adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus)
    except ValueError as e:
        print(f"Error initializing BMP280: {e}")
        return None


def read_baseline_pressure(sensor, reading_count, interval):
    """Reads baseline pressure from the sensor."""
    pressures = []
    for _ in range(reading_count):
        try:
            pressures.append(sensor.pressure)
            time.sleep(interval)
        except OSError as e:
            print(f"Error reading baseline pressure: {e}")
            return None
    if not pressures:
        return None
    return sum(pressures[2:]) / len(pressures[2:]) if len(pressures) > 2 else sum(pressures) / len(pressures)


def read_altitude(sensor, baseline_pressure):
    """Reads the relative altitude from the sensor."""
    try:
        return sensor.altitude
    except OSError as e:
        print(f"Error reading altitude: {e}")
        return None


def main():
    """Main function to read and display altitude."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    bmp280_sensor = initialize_bmp280(i2c_bus)
    if bmp280_sensor is None:
        return

    baseline_pressure = read_baseline_pressure(bmp280_sensor, BASELINE_READING_COUNT, BASELINE_READING_INTERVAL)
    if baseline_pressure is None:
        return

    try:
        while True:
            altitude = read_altitude(bmp280_sensor, baseline_pressure)
            if altitude is not None:
                print(f"Relative altitude: {altitude:05.2f} meters")
            time.sleep(ALTITUDE_READING_INTERVAL)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        i2c_bus.deinit()
        print("I2C bus deinitialized.")


if __name__ == "__main__":
    main()

