# Temperature and humidity monitoring program for Raspberry Pi 4 Model B
# Reads data from a UART temperature/humidity sensor and prints readings
# Includes error handling, alerts, and a graceful shutdown.

import serial
import time
import logging

# Configure logging for debugging and error tracking
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Alert thresholds
TEMPERATURE_THRESHOLD = 30.0  # Celsius
HUMIDITY_THRESHOLD = 70.0  # Percent

def initialize_serial(port, baud, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        logging.info(f"Serial port {port} initialized successfully.")
        return ser
    except serial.SerialException as e:
        logging.error(f"Error initializing serial port: {e}")
        return None

def read_sensor_data(serial_connection):
    """Reads temperature and humidity data from the serial port."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            try:
                temperature, humidity = map(float, line.split(','))
                return temperature, humidity
            except ValueError:
                logging.warning(f"Malformed data received: {line}")
                return None, None
        return None, None
    except serial.SerialException as e:
        logging.error(f"Serial read error: {e}")
        return None, None

def check_thresholds(temperature, humidity):
    """Checks if temperature or humidity exceeds the alert thresholds."""
    if temperature is not None and humidity is not None:
        if temperature > TEMPERATURE_THRESHOLD:
            logging.warning(f"High temperature alert: {temperature:.1f} °C")
        if humidity > HUMIDITY_THRESHOLD:
            logging.warning(f"High humidity alert: {humidity:.1f} %")

def main():
    """Main function to continuously read and process sensor data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        logging.error("Failed to initialize serial connection. Exiting.")
        return

    try:
        while True:
            temperature, humidity = read_sensor_data(serial_connection)

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f} °C, Humidity: {humidity:.1f} %")
                check_thresholds(temperature, humidity)

            time.sleep(1)

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            logging.info("Serial port closed.")

if __name__ == "__main__":
    main()

