import numpy as np
import matplotlib.pyplot as plt

# Configuration for the thermal imaging camera
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Initialize serial communication
try:
    serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
except serial.SerialException as e:
    print(f"Error opening serial port: {e}")
    exit(1)

# Function to read and process thermal data
def get_thermal_frame():
    """Reads a thermal frame from the serial port and returns it as a NumPy array."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if not line:
            return None

        try:
            pixels = [int(x) for x in line.split(',')]
            if len(pixels) != 768:
                return None

            return np.array(pixels).reshape((24, 32))
        except ValueError:
            return None
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

# Main loop for displaying thermal images
try:
    while True:
        thermal_frame = get_thermal_frame()
        if thermal_frame is not None:
            plt.imshow(thermal_frame, cmap='inferno', interpolation='nearest')
            plt.pause(0.1)
        else:
            time.sleep(0.1)
except KeyboardInterrupt:
    print("Program interrupted by user.")
finally:
    serial_connection.close()
    plt.close()

