import sys
import subprocess
import DOGProtocol as DOG  # Assuming this is your custom module
import RPi.GPIO as GPIO
import threading
import time

MANUAL = {
    "help": "Call 'help <command>' for details.\nCommands:\n\tdisplay\n\thelp\n\tstart\n\tstop\n\tsend",
    "start": "Start logging: start <filename>",
    "stop": "Stop logging: stop",
    "display": "Display log: display",
    "send": "Send data: send <data>",
    "write": "Write to log: write <data>",
}

class DOGController:
    """Controls the DOG device and logs data."""

    def __init__(self):
        """Initializes the controller."""
        self.is_running = False
        self.filename = None
        self.file = None
        self.receive_thread = None

    def handle_command(self, command, args):
        """Executes a command based on the provided arguments."""
        try:
            if command == "start":
                self.start_logging(args[0])
            elif command == "stop":
                self.stop_logging()
            elif command == "display":
                self.display_log()
            elif command == "send":
                self.send_data(" ".join(args))
            elif command == "write":
                self.write_to_log(" ".join(args))
            elif command == "help":
                if args:
                    print(MANUAL.get(args[0], "No help for this command."))
                else:
                    print(MANUAL["help"])
            else:
                print(f"Unknown command: {command}. Try 'help'.")
        except Exception as e:
            print(f"Error executing command: {e}")

    def start_logging(self, filename):
        """Starts logging data from the DOG device."""
        if self.is_running:
            print("Logging already running.")
            return

        try:
            self.filename = filename
            self.file = open(self.filename, "a+")  # Append mode with creation
            self.is_running = True

            # Start receiving data in a separate thread
            self.receive_thread = threading.Thread(target=self._receive_data, daemon=True)
            self.receive_thread.start()

            print(f"Logging started to {self.filename}")
        except Exception as e:
            print(f"Error starting logging: {e}")
            self.is_running = False
            if self.file:
                self.file.close()
            self.file = None


    def _receive_data(self):
        """Internal method to continuously receive and log data."""
        while self.is_running:
            try:
                data = DOG.receive()  # Assuming DOG.receive returns data or None
                if data:
                    self._write_to_log(data)
            except Exception as e:
                print(f"Error receiving or logging data: {e}")
                break  # Stop the loop on error
        self.stop_logging() # Ensure proper cleanup

    def stop_logging(self):
        """Stops logging data and cleans up resources."""
        if not self.is_running:
            print("Logging not running.")
            return

        self.is_running = False
        if self.receive_thread:
            self.receive_thread.join(timeout=1)  # Wait for thread to finish (with timeout)
        if self.file:
            try:
                self.file.close()
            except Exception as e:
                print(f"Error closing file: {e}")
        self.file = None
        self.filename = None
        print("Logging stopped.")


    def display_log(self):
        """Displays the contents of the log file."""
        if not self.filename:
            print("No log file active.")
            return

        try:
            with open(self.filename, "r") as f:
                print(f.read())
        except FileNotFoundError:
            print("Log file not found.")
        except Exception as e:
            print(f"Error displaying log: {e}")

    def send_data(self, data):
        """Sends data to the DOG device."""
        try:
            DOG.send(data)
            print(f"Sent: {data}")
        except Exception as e:
            print(f"Error sending data: {e}")

    def write_to_log(self, data):
        """Writes data directly to the log file."""
        if not self.file:
            print("No log file open.")
            return

        self._write_to_log(data)


    def _write_to_log(self, data):
        """Writes data to the log file."""
        try:
            self.file.write(data + "\n")
            self.file.flush()  # Ensure data is written immediately
        except Exception as e:
            print(f"Error writing to log: {e}")



def main():
    """Main function to run the DOG controller."""
    controller = DOGController()
    print("Starting DOG control...")

    try:
        while True:
            command = input("DOG> ").strip()
            args = command.split()
            if not args:
                continue  # Ignore empty input

            command_name = args[0].lower()
            controller.handle_command(command_name, args[1:]) # Pass arguments excluding the command

            if command_name == "exit":
                break

    except KeyboardInterrupt:
        print("\nExiting DOG control.")
    finally:
        controller.stop_logging() # Ensure logging is stopped on exit
        GPIO.cleanup()  # Clean up GPIO pins


if __name__ == "__main__":
    main()

