#!/usr/bin/env python3

import time
import board
import busio
import adafruit_fingerprint

# Configuration
I2C_SCL_PIN = board.SCL
I2C_SDA_PIN = board.SDA
AUTH_DATABASE = {1: "User1", 2: "User2", 3: "User3"}  # Example database

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(I2C_SCL_PIN, I2C_SDA_PIN)
    except ValueError as e:
        print(f"I2C Initialization Error: {e}")
        return None

def initialize_fingerprint_sensor(i2c_bus):
    """Initialize the fingerprint sensor."""
    try:
        return adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
    except RuntimeError as e:
        print(f"Fingerprint Sensor Initialization Error: {e}")
        return None

def acquire_fingerprint_image(sensor):
    """Acquire a fingerprint image."""
    print('Waiting for finger...')
    while sensor.get_image() != adafruit_fingerprint.OK:
        pass
    print('Templating...')
    if sensor.image_2_tz(1) != adafruit_fingerprint.OK:
        return None
    return 1

def search_fingerprint_database(sensor, database):
    """Search the fingerprint database for a match."""
    print('Searching...')
    if sensor.finger_search() != adafruit_fingerprint.OK:
        return None
    print('Fingerprint matched!')
    return sensor.get_template()

def authenticate_user(sensor, database):
    """Authenticate a user against the database."""
    if sensor is None:
        return None

    image = acquire_fingerprint_image(sensor)
    if image is None:
        return None

    template = search_fingerprint_database(sensor, database)
    if template is None:
        return None

    score = sensor.get_verified_template()
    if score is not None:
        for user_id, user_name in database.items():
            if user_id == score:
                return user_name, score
    return None

def main():
    """Main function to run the fingerprint authentication system."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    fingerprint_sensor = initialize_fingerprint_sensor(i2c_bus)
    if fingerprint_sensor is None:
        i2c_bus.deinit()
        return

    try:
        while True:
            auth_result = authenticate_user(fingerprint_sensor, AUTH_DATABASE)
            if auth_result:
                user_name, score = auth_result
                print(f'Access Granted for {user_name} with score {score}')
            else:
                print('Access Denied')
            time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        i2c_bus.deinit()
        print("I2C bus deinitialized.")

if __name__ == "__main__":
    main()

