PWM_FREQUENCY = 25000

# Initialize the GPIO library
GPIO.setmode(GPIO.BCM)
GPIO.setup(FAN_PIN, GPIO.OUT, initial=GPIO.LOW)

# Create a PWM instance for the fan
try:
    fan_pwm = GPIO.PWM(FAN_PIN, PWM_FREQUENCY)
    fan_pwm.start(0)  # Start with the fan off
except Exception as e:
    print(f"Error initializing PWM: {e}")
    print("Falling back to software PWM.")
    fan_pwm = None  # Indicate PWM failure

try:
    while True:
        try:
            # Get the desired fan speed from the user
            fan_speed = float(input("Enter fan speed (0-100): "))

            # Check if the input is within the valid range
            if 0 <= fan_speed <= 100:
                # Update the PWM duty cycle to control the fan speed
                if fan_pwm:
                    fan_pwm.ChangeDutyCycle(fan_speed)
                else:
                    print(f"Setting fan speed to: {fan_speed}")  # Simulate PWM
            else:
                print("Invalid fan speed. Please enter a value between 0 and 100.")

        except ValueError:
            print("Invalid input. Please enter a number.")
        except KeyboardInterrupt:
            print("\nExiting program.")
            break
        except Exception as e:
            print(f"An unexpected error occurred: {e}")
            break

except RuntimeError as e:
    print(f"RuntimeError: {e}")
    print("This likely means you are not running the script with sudo.")
except Exception as e:
    print(f"An unexpected error occurred: {e}")
finally:
    # Stop PWM and clean up GPIO pins
    if fan_pwm:
        fan_pwm.stop()
    GPIO.cleanup()

