# -*- coding: utf-8 -*-
"""
Reads illuminance from a BH1750 light sensor over I2C using a functional approach.
"""

import time
import smbus2
import RPi.GPIO as GPIO

# Constants
DEFAULT_I2C_ADDRESS = 0x23
CONTINUOUS_HIGH_RES_MODE = 0x10
I2C_BUS_NUMBER = 1
MEASUREMENT_DELAY_SECONDS = 0.120

def initialize_i2c_bus(bus_number):
    """Initializes the I2C bus."""
    try:
        return smbus2.SMBus(bus_number)
    except Exception as e:
        raise RuntimeError(f"Failed to initialize I2C bus: {e}")

def initialize_sensor(bus, address):
    """Initializes the BH1750 sensor."""
    try:
        bus.write_byte(address, CONTINUOUS_HIGH_RES_MODE)
        return True
    except Exception as e:
        raise RuntimeError(f"Failed to initialize BH1750 sensor: {e}")

def read_lux(bus, address):
    """Reads and converts the lux value from the sensor."""
    try:
        data = bus.read_i2c_block_data(address, CONTINUOUS_HIGH_RES_MODE, 2)
        raw_value = (data[0] << 8) | data[1]
        return raw_value / 1.2
    except Exception as e:
        raise RuntimeError(f"Failed to read lux value: {e}")

def main():
    """Main function to read and display illuminance."""
    i2c_address = DEFAULT_I2C_ADDRESS
    try:
        i2c_bus = initialize_i2c_bus(I2C_BUS_NUMBER)
        if not initialize_sensor(i2c_bus, i2c_address):
            raise RuntimeError("BH1750 sensor initialization failed.")

        while True:
            lux_value = read_lux(i2c_bus, i2c_address)
            print(f"Illuminance: {lux_value:.2f} lux")
            time.sleep(3)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    except RuntimeError as e:
        print(f"Error: {e}")
    finally:
        if 'i2c_bus' in locals() and i2c_bus:
            i2c_bus.close()
        GPIO.cleanup()

if __name__ == "__main__":
    main()

