#!/usr/bin/env python3

import atexit
import signal
import sys
import time

from rainbowhat.display import print_at
from rainbowhat.lights import set_rgb, rainbow, color
from rainbowhat.motors import stop
from rainbowhat.buzzer import beep, say
from rainbowhat import color as rh_color

# Constants
NUM_BITS = 3
MSB = 4
LSB = 1
MID = 2

# Hardware setup (adapt to your specific wiring)
RAINBOW_HAT = True

# Bit states (0 or 1)
bit_states = [0] * NUM_BITS

# Display buffer (for the 7-segment display)
display_buffer = [0] * 4

# Function to calculate the decimal value of the bits
def calculate_decimal_value():
    value = 0
    for i, state in enumerate(bit_states):
        if state:
            value += 2**(2-i)  # Adjusted for 0-indexed list
    return value

# Function to update the 7-segment display
def update_display(value):
    if RAINBOW_HAT:
        try:
            print_at(value, 0, 0)
            rh_color.show()
        except Exception as e:
            print(f"Error updating display: {e}", file=sys.stderr)

# Function to update the LEDs
def update_leds(value):
    if RAINBOW_HAT:
        try:
            set_rgb(value, 0, 0)  # Red LED
            rainbow(0.5, 0.2, 0.9, 128) # Blue LED rainbow
        except Exception as e:
            print(f"Error updating LEDs: {e}", file=sys.stderr)

# Function to update the APA102 strip (if available)
def update_apa102(value):
    if RAINBOW_HAT:
        try:
            color(value, 0, 0)  # Red pixel
        except Exception as e:
            print(f"Error updating APA102: {e}", file=sys.stderr)

# Function to sound the buzzer
def sound_buzzer():
    if RAINBOW_HAT:
        try:
            beep(0.5)
        except Exception as e:
            print(f"Error sounding buzzer: {e}", file=sys.stderr)

# Function to handle a bit flip
def flip_bit(bit_index):
    try:
        bit_states[bit_index] = 1 - bit_states[bit_index]
        print(f"Bit {bit_index} flipped.")

        decimal_value = calculate_decimal_value()
        update_display(decimal_value)
        update_leds(decimal_value)
        update_apa102(decimal_value)
        sound_buzzer()

    except Exception as e:
        print(f"Error flipping bit: {e}", file=sys.stderr)

# Touchpad press handler
def touch_pressed(channel):
    if channel == 5:
        flip_bit(0)
    elif channel == 6:
        flip_bit(1)
    elif channel == 12:
        flip_bit(2)
    else:
        print(f"Unknown touchpad channel: {channel}", file=sys.stderr)

# Function to handle program exit
def cleanup():
    print("Exiting...")
    if RAINBOW_HAT:
        try:
            stop()  # Stop motors
            set_rgb(0, 0, 0)  # Turn off LEDs
            rainbow(0, 0, 0, 0) # Turn off rainbow LED
            color(0, 0, 0) # Turn off APA102
        except Exception as e:
            print(f"Error during cleanup: {e}", file=sys.stderr)

# Register cleanup function
atexit.register(cleanup)

# Signal handler for graceful exit
def signal_handler(sig, frame):
    print('You pressed Ctrl+C!')
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Main loop (using signal.pause for event-driven behavior)
if __name__ == "__main__":
    print("Binary Color Demo started. Press Ctrl+C to exit.")
    try:
        signal.pause()
    except KeyboardInterrupt:
        print("Exiting...")
        cleanup()
        sys.exit(0)

