import random

# Define the GPIO pin for the LED
LED_PIN = 17

def setup_gpio():
    """Set up GPIO mode and LED pin."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LED_PIN, GPIO.OUT)

def read_light_level():
    """Simulate reading an ambient light sensor."""
    return random.randint(0, 100)

def control_led(light_level):
    """Control the LED based on the light level."""
    if light_level < 50:
        GPIO.output(LED_PIN, GPIO.HIGH)
        return "ON"
    else:
        GPIO.output(LED_PIN, GPIO.LOW)
        return "OFF"

def main():
    """Main function to simulate light sensor and control LED."""
    setup_gpio()
    try:
        for cycle in range(5):
            light_level = read_light_level()
            led_status = control_led(light_level)
            print(f"Cycle {cycle + 1}: Light Level = {light_level}%, LED is {led_status}")
            time.sleep(2)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        GPIO.output(LED_PIN, GPIO.LOW)  # Ensure LED is off
        GPIO.cleanup()  # Release GPIO resources

if __name__ == "__main__":
    main()

