from Adafruit_MotorHAT import Adafruit_MotorHAT as MotorHATBase, MotorHATError

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
MIN_PWM_FREQUENCY = 100  # Hz
MAX_PWM_FREQUENCY = 5000 # Hz
DEFAULT_PWM_FREQUENCY = 60  # Hz
SPEED_RANGE = list(range(0, 256))


def _validate_pwm_frequency(frequency: int) -> int:
    """Validates and adjusts the PWM frequency."""
    if not isinstance(frequency, int):
        raise TypeError("PWM frequency must be an integer.")
    if frequency < MIN_PWM_FREQUENCY:
        logger.warning(f"PWM frequency {frequency} Hz is below the recommended minimum of {MIN_PWM_FREQUENCY} Hz.")
        return MIN_PWM_FREQUENCY
    if frequency > MAX_PWM_FREQUENCY:
        logger.warning(f"PWM frequency {frequency} Hz is above the recommended maximum of {MAX_PWM_FREQUENCY} Hz.")
        return MAX_PWM_FREQUENCY
    return frequency


def _validate_speed(speed: int) -> int:
    """Validates and adjusts the motor speed."""
    if not isinstance(speed, int):
        raise TypeError("Speed must be an integer.")
    if not -255 <= speed <= 255:
        raise ValueError("Speed must be within the range [-255, 255].")
    return speed


def _create_motor_mapping(hat, frequency: int):
    """Creates a mapping of motor numbers to motor objects."""
    return {
        i: DCMotor(hat, i, frequency)
        for i in range(1, 5)  # Motor numbers 1-4 are supported
    }


class DCMotor:
    """Represents a single DC motor controlled by the Motor HAT."""

    def __init__(self, hat, motor_no: int, frequency: int):
        """Initializes a DCMotor object."""
        if not isinstance(motor_no, int) or motor_no not in (1, 2, 3, 4):
            raise ValueError("Motor number must be an integer between 1 and 4.")
        self.motor = hat.getMotor(motor_no)
        self.motor_no = motor_no
        self.frequency = frequency
        self.last_speed = None
        self.is_running = False
        self.invert = False  # Flag to invert motor direction
        self._set_pwm_freq(frequency)
        self.stop()  # Ensure motor is initially stopped

    def _set_pwm_freq(self, frequency: int):
        """Sets the PWM frequency for the motor."""
        try:
            self.motor.setPWMFreq(frequency)
            self.frequency = frequency
            logger.debug(f"Motor {self.motor_no} PWM frequency set to {frequency} Hz.")
        except MotorHATError as e:
            logger.error(f"Failed to set PWM frequency for motor {self.motor_no}: {e}")
            raise

    def set_speed(self, speed: int):
        """Sets the speed of the motor."""
        try:
            speed = _validate_speed(speed)
            if speed == 0:
                self.stop()
                return

            if self.last_speed == speed and self.is_running:
                return  # Avoid redundant writes

            direction = speed > 0
            if self.invert:
                direction = not direction

            speed = abs(speed)
            if speed not in SPEED_RANGE:
                logger.warning(f"Invalid speed {speed}. Using closest valid speed: {min(SPEED_RANGE, key=lambda x:abs(x-speed))}")
                speed = min(SPEED_RANGE, key=lambda x:abs(x-speed))

            self.motor.run(direction + 1)  # Convert boolean to motor direction (1 or 2)
            self.motor.setSpeed(speed)
            self.last_speed = speed
            self.is_running = True
            logger.debug(f"Motor {self.motor_no} speed set to {speed}.")

        except (ValueError, TypeError, MotorHATError) as e:
            logger.error(f"Failed to set speed for motor {self.motor_no}: {e}")
            raise

    def stop(self):
        """Stops the motor."""
        try:
            self.motor.run(0)  # Stop the motor
            self.last_speed = 0
            self.is_running = False
            logger.debug(f"Motor {self.motor_no} stopped.")
        except MotorHATError as e:
            logger.error(f"Failed to stop motor {self.motor_no}: {e}")
            raise

    def get_status(self) -> dict:
        """Returns the motor status as a dictionary."""
        return {
            "motor_no": self.motor_no,
            "frequency": self.frequency,
            "invert": self.invert,
            "last_speed": self.last_speed,
        }


class MotorHATExtra(MotorHATBase):
    """
    Extends the Adafruit_MotorHAT class to add functionalities for DC motors.

    Provides a simplified interface for controlling multiple DC motors
    with error handling and resource management.
    """

    def __init__(self, i2c_busnum=1, i2c_addr=0x60, freq=DEFAULT_PWM_FREQUENCY, *args, **kwargs):
        """Initializes the MotorHATExtra object."""
        try:
            self._pwm_frequency = _validate_pwm_frequency(freq)
            super().__init__(i2c_busnum=i2c_busnum, i2c_addr=i2c_addr, freq=self._pwm_frequency, *args, **kwargs)
            self._motors = _create_motor_mapping(self, self._pwm_frequency)
            atexit.register(self._cleanup)
            signal.signal(signal.SIGTERM, self._cleanup_signal)
            signal.signal(signal.SIGINT, self._cleanup_signal)
            logger.info("Motor HAT initialized successfully.")

        except MotorHATError as e:
            logger.error(f"Failed to initialize Motor HAT: {e}")
            raise  # Re-raise the exception to be handled by the caller
        except Exception as e:
            logger.error(f"An unexpected error occurred during initialization: {e}")
            raise

    def _cleanup(self, *args):
        """Releases all motors and stops them."""
        logger.info("Cleaning up motors...")
        for motor in self._motors.values():
            motor.stop()
        logger.info("Cleanup complete.")

    def _cleanup_signal(self, *args):
        self._cleanup()
        exit(0)

    def set_pwm_freq(self, frequency: int):
        """Sets the PWM frequency for all motors."""
        try:
            frequency = _validate_pwm_frequency(frequency)
            if frequency != self._pwm_frequency:
                self._pwm_frequency = frequency
                for motor in self._motors.values():
                    motor._set_pwm_freq(frequency)
                logger.info(f"PWM frequency set to {frequency} Hz.")
            else:
                logger.warning(f"PWM frequency {frequency} Hz is the same as the current frequency.")
        except ValueError as e:
            logger.error(f"Invalid PWM frequency: {e}")
            raise
        except MotorHATError as e:
            logger.error(f"Failed to set PWM frequency: {e}")
            raise

    def get_pwm_freq(self) -> int:
        """Returns the current PWM frequency."""
        return self._pwm_frequency

    def get_motor(self, motor_no: int) -> DCMotor:
        """Returns the specified DCMotor object."""
        try:
            return self._motors[motor_no]
        except KeyError:
            raise ValueError(f"Invalid motor number: {motor_no}")

    def get_status(self) -> dict:
        """Returns the status of all motors."""
        return {motor_no: motor.get_status() for motor_no, motor in self._motors.items()}


if __name__ == "__main__":
    try:
        hat = MotorHATExtra(freq=100)
        motor1 = hat.get_motor(1)
        motor2 = hat.get_motor(2)

        motor1.set_speed(100)
        motor2.set_speed(80)
        time.sleep(2)

        motor1.stop()
        motor2.stop()

    except MotorHATError as e:
        logger.error(f"Motor HAT error: {e}")
    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")

