import RPi.GPIO as GPIO
import time

# Define GPIO pins for the line following sensors and motors
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6
LEFT_MOTOR_PIN = 16
RIGHT_MOTOR_PIN = 26

# Define the maximum number of loop iterations
MAX_LOOPS = 20

def setup_gpio():
    """Set up GPIO pins for line following."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN)
        GPIO.setup(LEFT_MOTOR_PIN, GPIO.OUT)
        GPIO.setup(RIGHT_MOTOR_PIN, GPIO.OUT)
    except Exception as e:
        print(f"GPIO setup error: {e}")
        return False
    return True

def read_sensor(sensor_pin):
    """Read the state of a line following sensor."""
    try:
        return GPIO.input(sensor_pin)
    except Exception as e:
        print(f"Sensor read error: {e}")
        return None

def control_motors(left_motor_state, right_motor_state):
    """Control the motor outputs based on sensor readings."""
    GPIO.output(LEFT_MOTOR_PIN, left_motor_state)
    GPIO.output(RIGHT_MOTOR_PIN, right_motor_state)

def main():
    """Main function to run the line following control loop."""
    if not setup_gpio():
        return

    try:
        for _ in range(MAX_LOOPS):
            left_sensor_value = read_sensor(LEFT_SENSOR_PIN)
            right_sensor_value = read_sensor(RIGHT_SENSOR_PIN)

            if left_sensor_value is None or right_sensor_value is None:
                control_motors(False, False)  # Stop motors if sensor read failed
                continue

            if left_sensor_value == GPIO.LOW and right_sensor_value == GPIO.HIGH:
                # Only the left sensor is on the line, turn right
                control_motors(False, True)
            elif left_sensor_value == GPIO.HIGH and right_sensor_value == GPIO.LOW:
                # Only the right sensor is on the line, turn left
                control_motors(True, False)
            elif left_sensor_value == GPIO.LOW and right_sensor_value == GPIO.LOW:
                # Both sensors are on the line, move straight
                control_motors(True, True)
            else:
                # Neither sensor is on the line, stop
                control_motors(False, False)

            time.sleep(0.1)

    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

