import time
import board
import busio
import adafruit_seesaw.seesaw
import RPi.GPIO as GPIO

# Define constants
I2C_ADDRESS = 0x34
PUMP_GPIO_PIN = 17
MOISTURE_THRESHOLD = 500
READ_INTERVAL_SECONDS = 10

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_seesaw_sensor(i2c_bus):
    """Initialize the Seesaw soil moisture sensor."""
    try:
        sensor = adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=I2C_ADDRESS)
        return sensor
    except Exception as e:
        print(f"Error initializing Seesaw sensor: {e}")
        return None

def initialize_gpio(pump_pin):
    """Initialize the GPIO pin for the water pump relay."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pump_pin, GPIO.OUT)
    GPIO.output(pump_pin, GPIO.LOW)  # Ensure pump is initially off

def read_soil_moisture(sensor):
    """Read the soil moisture level from the sensor."""
    try:
        moisture_level = sensor.moisture_read()
        return moisture_level
    except Exception as e:
        print(f"Error reading soil moisture: {e}")
        return None

def control_water_pump(pump_pin, moisture_level, threshold):
    """Control the water pump based on the soil moisture level."""
    if moisture_level is not None:
        if moisture_level < threshold:
            GPIO.output(pump_pin, GPIO.HIGH)  # Activate pump
            pump_status = "ON"
        else:
            GPIO.output(pump_pin, GPIO.LOW)  # Deactivate pump
            pump_status = "OFF"
        print(f"Soil Moisture: {moisture_level}, Pump: {pump_status}")

def main():
    """Main function to continuously monitor soil moisture and control the water pump."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_seesaw_sensor(i2c_bus)
    if sensor is None:
        return

    initialize_gpio(PUMP_GPIO_PIN)

    try:
        while True:
            moisture = read_soil_moisture(sensor)
            if moisture is not None:
                control_water_pump(PUMP_GPIO_PIN, moisture, MOISTURE_THRESHOLD)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        GPIO.output(PUMP_GPIO_PIN, GPIO.LOW)  # Ensure pump is off
        GPIO.cleanup()  # Release GPIO resources
        if i2c_bus:
            i2c_bus.deinit()

if __name__ == "__main__":
    main()

