#!/usr/bin/env python3

"""
Servo Motor Control Program for Raspberry Pi using Modbus RTU.
This program communicates with a servo motor via Modbus RTU over UART to
control its position. It uses a functional programming style with proper
error handling and resource management.
"""

import time
import serial
import logging
import sys
import signal
import struct
from functools import partial

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
MODBUS_SLAVE_ADDRESS = 1
UART_PORT = '/dev/serial0'
BAUDRATE = 115200
TIMEOUT = 0.5

# Functional error handling
def handle_error(error_message, *args):
    """Logs an error message and returns an error code."""
    logging.error(error_message)
    return -1

# Modbus register addresses (functional approach)
REGISTER_ADDRESSES = {
    'position': 0x0000,
    'speed': 0x0002,
    'status': 0x0004,
    'error': 0x0006
}

def get_register_address(register_name):
    """Retrieves the register address for a given name."""
    return REGISTER_ADDRESSES.get(register_name)

# Modbus function codes
FUNCTION_CODES = {
    'read_holding_registers': 0x03,
    'write_single_register': 0x06
}

def get_function_code(function_name):
    """Retrieves the Modbus function code for a given name."""
    return FUNCTION_CODES.get(function_name)

# Modbus message building functions
def create_modbus_message(slave_address, function_code, register_address, value=None):
    """Creates a Modbus RTU message."""
    if function_code == get_function_code('read_holding_registers'):
        return create_read_holding_registers_message(slave_address, register_address)
    elif function_code == get_function_code('write_single_register'):
        return create_write_single_register_message(slave_address, register_address, value)
    else:
        raise ValueError("Invalid function code")

def create_read_holding_registers_message(slave_address, register_address):
    """Creates a Modbus RTU message for reading holding registers."""
    return struct.pack('>BBHH', slave_address, get_function_code('read_holding_registers'), register_address, 1)

def create_write_single_register_message(slave_address, register_address, value):
    """Creates a Modbus RTU message for writing a single register."""
    return struct.pack('>BBHH', slave_address, get_function_code('write_single_register'), register_address, value)

# Modbus CRC calculation (pure function)
def calculate_crc(message):
    """Calculates the Modbus CRC checksum."""
    crc = 0xFFFF
    for byte in message:
        crc ^= byte
        for _ in range(8):
            if crc & 0x0001:
                crc >>= 1
                crc ^= 0xA001
            else:
                crc >>= 1
    return crc

def append_crc(message):
    """Appends the CRC to the message."""
    crc = calculate_crc(message)
    return message + struct.pack('>H', crc)

# Modbus message parsing functions
def parse_modbus_message(message):
    """Parses a Modbus RTU message."""
    try:
        slave_address = message[0]
        function_code = message[1]
        if function_code == get_function_code('read_holding_registers'):
            return parse_read_holding_registers_message(message)
        else:
            raise ValueError("Unsupported function code")
    except Exception as e:
        raise ValueError(f"Invalid Modbus message: {e}")

def parse_read_holding_registers_message(message):
    """Parses a Modbus RTU message for reading holding registers."""
    try:
        return struct.unpack('>HH', message[3:7])[0]  # Extract register value
    except Exception as e:
        raise ValueError(f"Error parsing read holding registers message: {e}")

# Serial communication functions
def open_serial_port(port, baudrate, timeout):
    """Opens a serial port."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        raise serial.SerialException(f"Could not open serial port {port}: {e}")

def close_serial_port(ser):
    """Closes a serial port."""
    try:
        ser.close()
    except Exception as e:
        logging.error(f"Error closing serial port: {e}")

def send_modbus_message(ser, message):
    """Sends a Modbus message over the serial port."""
    try:
        ser.write(message)
    except serial.SerialException as e:
        raise serial.SerialException(f"Error writing to serial port: {e}")

def read_modbus_message(ser, timeout=TIMEOUT):
    """Reads a Modbus message from the serial port with a timeout."""
    start_time = time.time()
    response = bytes()
    while time.time() - start_time < timeout:
        if ser.in_waiting:
            response += ser.read(ser.in_waiting)
            if len(response) >= 5:  # Minimal response size
                return response
        else:
            time.sleep(0.01)  # Prevent busy-waiting
    raise serial.SerialException("Timeout reading from serial port")

def send_and_receive_modbus_message(ser, message):
    """Sends a Modbus message and returns the raw response."""
    send_modbus_message(ser, message)
    return read_modbus_message(ser)

# Resource management functions
def with_serial_port(port, baudrate, timeout, ser_op):
    """Manages serial port resource."""
    try:
        ser = open_serial_port(port, baudrate, timeout)
        result = ser_op(ser)
        return result
    except serial.SerialException as e:
        logging.error(f"Serial port error: {e}")
        return None
    finally:
        if 'ser' in locals() and ser.is_open:
            close_serial_port(ser)

def with_modbus_transaction(ser, slave_address, function_code, register_address, value, op):
    """Manages Modbus transaction resource."""
    try:
        message = create_modbus_message(slave_address, function_code, register_address, value)
        message_with_crc = append_crc(message)
        response = send_and_receive_modbus_message(ser, message_with_crc)
        return op(response)
    except (ValueError, serial.SerialException) as e:
        logging.error(f"Modbus transaction error: {e}")
        return None

# Servo motor control functions
def read_servo_position(ser, slave_address, register_address):
    """Reads the servo motor position."""
    return with_modbus_transaction(ser, slave_address, get_function_code('read_holding_registers'), register_address, None, parse_modbus_message)

def write_servo_position(ser, slave_address, register_address, value):
    """Writes a new servo motor position."""
    return with_modbus_transaction(ser, slave_address, get_function_code('write_single_register'), register_address, value, lambda response: True) # No need to parse response for write

def set_servo_position(ser, position):
    """Sets the servo motor to a specific position."""
    if not 0 <= position <= 100:
        return handle_error("Invalid position. Must be between 0 and 100.")
    register_address = get_register_address('position')
    if register_address is None:
        return handle_error("Invalid register address for position.")
    return write_servo_position(ser, MODBUS_SLAVE_ADDRESS, register_address, int(position)) is not None

def get_servo_position(ser):
    """Gets the current servo motor position."""
    register_address = get_register_address('position')
    if register_address is None:
        return handle_error("Invalid register address for position.")
    position = read_servo_position(ser, MODBUS_SLAVE_ADDRESS, register_address)
    if position is None:
        return handle_error("Error reading servo position.")
    return position

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    logging.info('Exiting gracefully...')
    sys.exit(0)

# Main program orchestration
def main():
    """Main function to control the servo motor."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    def ser_operation(ser):
        """Serial port operation to be performed."""
        position = get_servo_position(ser)
        if position is not None:
            logging.info(f'Current servo position: {position}')
        else:
            return -1

        new_position = 50
        if set_servo_position(ser, new_position):
            logging.info(f'Setting servo to position: {new_position}')
            time.sleep(2)
            current_position = get_servo_position(ser)
            if current_position is not None:
                logging.info(f'Current servo position: {current_position}')
            else:
                return -1
        else:
            return -1
        return 0

    result = with_serial_port(UART_PORT, BAUDRATE, TIMEOUT, ser_operation)
    if result == -1:
        logging.error("Servo control failed.")
        sys.exit(1)
    logging.info("Servo control completed successfully.")

# Entry point
if __name__ == '__main__':
    main()

