import time
from Adafruit_PWM_Servo_Driver import PWM

# Constants for the servo driver and servo angles
PWM_FREQUENCY = 60
MIN_SERVO_ANGLE = 0
MAX_SERVO_ANGLE = 180
SERVO_CHANNEL_GRABBER = 0
GRAB_ANGLE = 90
RELEASE_ANGLE = 150
MOVEMENT_INCREMENT = 5
MOVEMENT_DELAY = 0.04


def initialize_pwm():
    """Initializes the PWM driver for servo control."""
    try:
        pwm = PWM(0x40)
        pwm.setPWMFreq(PWM_FREQUENCY)
        return pwm
    except Exception as e:
        print(f"Error initializing PWM driver: {e}")
        return None


def calculate_pulse(angle):
    """Calculates the pulse width for a given angle."""
    return int((float(angle) / MAX_SERVO_ANGLE) * 4096)


def move_servo(pwm, servo_channel, target_angle):
    """Moves the specified servo to the target angle."""
    if not MIN_SERVO_ANGLE <= target_angle <= MAX_SERVO_ANGLE:
        print(f"Invalid target angle: {target_angle}. Angle must be between {MIN_SERVO_ANGLE} and {MAX_SERVO_ANGLE}.")
        return

    try:
        current_angle = MIN_SERVO_ANGLE
        if target_angle > current_angle:
            for angle in range(current_angle, target_angle, MOVEMENT_INCREMENT):
                pulse = calculate_pulse(angle)
                pwm.setPWM(servo_channel, 0, pulse)
                time.sleep(MOVEMENT_DELAY)
        else:
            for angle in range(current_angle, target_angle, -MOVEMENT_INCREMENT):
                pulse = calculate_pulse(angle)
                pwm.setPWM(servo_channel, 0, pulse)
                time.sleep(MOVEMENT_DELAY)

        pulse = calculate_pulse(target_angle)
        pwm.setPWM(servo_channel, 0, pulse)
        time.sleep(MOVEMENT_DELAY)

    except Exception as e:
        print(f"Error moving servo on channel {servo_channel}: {e}")


def grab_object(pwm):
    """Closes the claw to grab an object."""
    move_servo(pwm, SERVO_CHANNEL_GRABBER, GRAB_ANGLE)


def release_object(pwm):
    """Opens the claw to release an object."""
    move_servo(pwm, SERVO_CHANNEL_GRABBER, RELEASE_ANGLE)


def main():
    """Main function to demonstrate servo control."""
    pwm = initialize_pwm()
    if pwm is None:
        return

    try:
        grab_object(pwm)
        time.sleep(1)
        release_object(pwm)
        time.sleep(1)

    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Releasing resources and exiting.")
        # No specific cleanup needed for Adafruit_PWM_Servo_Driver, but good practice to include a final message.


if __name__ == "__main__":
    main()

