import time
from functools import reduce

# Constants for servoblaster control
SERVO_BLASTER_DEVICE = "/dev/servoblaster"
HORIZONTAL_SERVO_CHANNEL = 0
VERTICAL_SERVO_CHANNEL = 1
LASER_GPIO_PIN = 17  # BCM pin 11, physical pin 11

# Servo positions (adjust as needed)
HORIZONTAL_POSITIONS = [133, 128, 122, 133, 128, 122, 133, 128, 122, 128]
VERTICAL_POSITIONS = [75, 75, 75, 72, 72, 72, 68, 68, 68, 90]


class GPIOController:
    """Handles GPIO pin control."""

    def __init__(self, pin):
        self.pin = pin
        self._setup_gpio()

    def _setup_gpio(self):
        """Initializes the GPIO pin."""
        try:
            os.system(f"sudo echo {self.pin} > /sys/class/gpio/export")
            os.system(f"sudo echo out > /sys/class/gpio/gpio{self.pin}/direction")
        except Exception as e:
            raise IOError(f"Error setting up GPIO pin {self.pin}: {e}")

    def set_pin(self, value):
        """Sets the GPIO pin to the given value (0 or 1)."""
        try:
            os.system(f"sudo echo {value} > /sys/class/gpio/gpio{self.pin}/value")
        except Exception as e:
            raise IOError(f"Error setting GPIO pin {self.pin} to value {value}: {e}")

    def __del__(self):
        try:
            os.system(f"sudo echo {self.pin} > /sys/class/gpio/unexport")
        except Exception as e:
            print(f"Error unexporting GPIO pin {self.pin}: {e}")  # Non-fatal error


class AimingController:
    """Controls the laser and servos."""

    def __init__(self, ld, hd, laser_pin=LASER_GPIO_PIN):
        self.ld = ld
        self.hd = hd
        self.laser_pin = laser_pin
        self.laser_controller = GPIOController(self.laser_pin)
        self.servo_blaster_path = SERVO_BLASTER_DEVICE
        self.horizontal_positions = HORIZONTAL_POSITIONS
        self.vertical_positions = VERTICAL_POSITIONS

        self.horizontal_map = list(enumerate(self.horizontal_positions))
        self.vertical_map = list(enumerate(self.vertical_positions))

        self.check_servoblaster_device()


    def check_servoblaster_device(self):
        """Checks if the servoblaster device exists."""
        if not os.path.exists(self.servo_blaster_path):
            raise IOError(f"Servoblaster device not found: {self.servo_blaster_path}")

    def aim_at_position(self, block_number):
        """Aims at a single block."""
        try:
            with open(self.servo_blaster_path, "w") as fd:
                horizontal_pos = self.horizontal_positions[block_number]
                vertical_pos = self.vertical_positions[block_number]
                fd.write(f"{HORIZONTAL_SERVO_CHANNEL}={horizontal_pos}\n")
                fd.write(f"{VERTICAL_SERVO_CHANNEL}={vertical_pos}\n")
            time.sleep(self.ld / 2)
            self.laser_controller.set_pin(1)
            time.sleep(self.hd)
            self.laser_controller.set_pin(0)
            time.sleep(self.ld / 2)

        except IOError as e:
            raise IOError(f"Error aiming at block {block_number}: {e}")


    def aim_blocks(self, input_numbers):
