# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock (RTC) Driver for Raspberry Pi

This module provides a robust and optimized driver for the DS1338 RTC chip.
"""

import smbus
import time
import datetime
import logging
import os
import signal

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
DEFAULT_I2C_BUS = 1
DEFAULT_I2C_ADDRESS = 0x68

# Register Addresses (DS1338 compatible, but adjusted for BCM pin assignments)
REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DAY = 0x03
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06
REG_CONTROL = 0x07
REG_STATUS = 0x0F  # Added Status Register address
REG_A = 0x08
REG_B = 0x09
REG_C = 0x0A
REG_D = 0x0B

# Bitmasks for register operations
BIT_7 = 0x80

# Global Variables
shutdown_flag = False

class DS1338Error(Exception):
    """Custom exception for DS1338 errors."""
    pass

def bcd_to_int(bcd_value):
    """Converts BCD to integer."""
    try:
        return (bcd_value >> 4) * 10 + (bcd_value & 0x0F)
    except TypeError:
        logging.error(f"Invalid BCD value: {bcd_value}")
        return None

def int_to_bcd(int_value):
    """Converts integer to BCD."""
    if not 0 <= int_value <= 99:
        raise ValueError("Integer value must be between 0 and 99 for BCD conversion.")
    return (int_value // 10 << 4) | (int_value % 10)

def read_register(bus, register):
    """Reads a byte from the specified register."""
    try:
        return bus.read_byte_data(DEFAULT_I2C_ADDRESS, register)
    except OSError as e:
        logging.error(f"I2C read error: {e}")
        return None

def write_register(bus, register, value):
    """Writes a byte to the specified register."""
    try:
        bus.write_byte_data(DEFAULT_I2C_ADDRESS, register, value)
    except OSError as e:
        logging.error(f"I2C write error: {e}")


