import time
import datetime
import smbus
import json
import logging
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Default configuration values
DEFAULT_GPIO_PIN = 17
DEFAULT_TRANSMISSION_REPEAT = 3

def load_configuration(config_file):
    """Loads configuration from a JSON file."""
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
        return config
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_file}")
        sys.exit(1)
    except json.JSONDecodeError:
        logging.error(f"Invalid JSON format in configuration file: {config_file}")
        sys.exit(1)

def get_rf_code(config, zone, state):
    """Retrieves the RF code from the configuration."""
    if zone not in config:
        logging.error(f"Zone '{zone}' not found in configuration.")
        return None
    if state not in config[zone]:
        logging.error(f"State '{state}' not found for zone '{zone}' in configuration.")
        return None
    return config[zone][state]

def get_gpio_pin(config):
    """Retrieves the GPIO pin from the configuration."""
    return config.get('gpio_pin', DEFAULT_GPIO_PIN)

def get_transmission_repeat(config):
    """Retrieves the transmission repeat count from the configuration."""
    return config.get('transmission_repeat', DEFAULT_TRANSMISSION_REPEAT)

def read_rtc_time():
    """Reads the current time from the DS3231 RTC module."""
    try:
        bus = smbus.SMBus(1)  # Use I2C bus 1
        bus.write_byte(0x68, 0x00)  # Point to the seconds register
        data = bus.read_i2c_block_data(0x68, 0x00, 7)
        seconds = bcd_to_decimal(data[0])
        minutes = bcd_to_decimal(data[1])
        hours = bcd_to_decimal(data[2] & 0x3F)  # Mask out AM/PM bit
        return datetime.datetime(datetime.date.today().year, datetime.date.today().month, datetime.date.today().day, hours, minutes, seconds)
    except Exception as e:
        logging.warning(f"Failed to read RTC time: {e}. Falling back to system time.")
        return datetime.datetime.now()

def bcd_to_decimal(bcd):
    """Converts BCD to decimal."""
    return (bcd >> 4) * 10 + (bcd & 0x0F)

def transmit_rf_code(gpio_pin, rf_code, transmission_repeat):
    """Transmits the RF code using the specified GPIO pin."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(gpio_pin, GPIO.OUT)
        GPIO.output(gpio_pin, GPIO.LOW)  # Ensure the pin is initially low
        time.sleep(0.001) # Small delay
        for _ in range(transmission_repeat):
            for bit in rf_code:
                if bit == '1':
                    GPIO.output(gpio_pin, GPIO.HIGH)
                    time.sleep(0.001)
                    GPIO.output(gpio_pin, GPIO.LOW)
                    time.sleep(0.001)
                else:
                    GPIO.output(gpio_pin, GPIO.LOW)
                    time.sleep(0.001)
                    GPIO.output(gpio_pin, GPIO.HIGH)
                    time.sleep(0.001)
            time.sleep(0.01) # Gap between repeats
    except Exception as e:
        logging.error(f"Error transmitting RF code: {e}")
        return False
    finally:
        GPIO.cleanup(gpio_pin) # Clean up GPIO pin
    return True

def main():
    """Main function to control irrigation zones."""
    if len(sys.argv) != 3:
        logging.error("Usage: python script.py <zone> <on|off>")
        sys.exit(1)

    zone, state = sys.argv[1], sys.argv[2]

    config = load_configuration("irrigation_config.json")
    gpio_pin = get_gpio_pin(config)
    transmission_repeat = get_transmission_repeat(config)
    rf_code = get_rf_code(config, zone, state)

    if rf_code is None:
        sys.exit(1)

    current_time = read_rtc_time()
    logging.info(f"Current time: {current_time}")
    logging.info(f"Transmitting RF code for zone '{zone}', state '{state}' on GPIO pin {gpio_pin}, repeating {transmission_repeat} times.")

    if transmit_rf_code(gpio_pin, rf_code, transmission_repeat):
        logging.info("RF code transmitted successfully.")
    else:
        logging.error("RF code transmission failed.")

if __name__ == "__main__":
    main()

