import serial
import time
import pynmea2

# Configuration
GPS_PORT = '/dev/ttyUSB0'
LOG_FILE = 'gps_coordinates_log.txt'
READ_TIMEOUT = 1  # seconds

def initialize_gps_port(port, baudrate=9600, timeout=READ_TIMEOUT):
    """Initializes the GPS serial port."""
    try:
        ser = serial.Serial(port, baudrate=baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error initializing GPS port: {e}")
        return None

def parse_gps_data(data):
    """Parses GPS data to extract latitude, longitude, and altitude."""
    try:
        msg = pynmea2.parse(data)
        latitude = msg.latitude
        longitude = msg.longitude
        altitude = msg.altitude
        return latitude, longitude, altitude
    except pynmea2.ParseError:
        return None, None, None

def log_coordinates(latitude, longitude, altitude, log_file):
    """Logs the GPS coordinates to a file."""
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f"{timestamp}, {latitude}, {longitude}, {altitude}\n"
    try:
        with open(log_file, 'a') as file:
            file.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read GPS data, parse, log, and print."""
    gps_port = initialize_gps_port(GPS_PORT)

    if gps_port is None:
        print("Failed to initialize GPS port. Exiting.")
        return

    try:
        while True:
            try:
                line = gps_port.readline().decode('ascii', errors='replace').strip()
            except serial.SerialException as e:
                print(f"Error reading from GPS port: {e}")
                break

            if line.startswith('$GPGGA'):
                latitude, longitude, altitude = parse_gps_data(line)

                if latitude is not None and longitude is not None and altitude is not None:
                    print(f"Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude}")
                    log_coordinates(latitude, longitude, altitude, LOG_FILE)

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        if gps_port and gps_port.is_open:
            gps_port.close()
            print("GPS port closed.")

if __name__ == "__main__":
    main()

