import RPi.GPIO as GPIO
import serial
import logging
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
DEFAULT_SERIAL_PORT = '/dev/ttyUSB0'
DEFAULT_BAUDRATE = 9600
DEFAULT_TIMEOUT = 1
DATA_FILE = 'data.json'
API_ENDPOINT = '/data'
FLASK_HOST = '0.0.0.0'
FLASK_PORT = 5000

# Global variables
app = Flask(__name__)
data_lock = threading.Lock()
data = [{"id": 1, "name": "CHIPS", "done": False}, {"id": 2, "name": "garden", "done": False}]
serial_port = None
serial_lock = threading.Lock()
shutdown_flag = False

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    global shutdown_flag
    logging.info('Shutting down gracefully...')
    shutdown_flag = True
    close_serial_port()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def open_serial_port(port=DEFAULT_SERIAL_PORT, baudrate=DEFAULT_BAUDRATE, timeout=DEFAULT_TIMEOUT):
    """Opens the serial port with retry logic and thread safety."""
    global serial_port
    retries = 3
    for i in range(retries):
        try:
            with serial_lock:
                if serial_port is None or not serial_port.is_open:
                    serial_port = serial.Serial(port, baudrate, timeout=timeout)
                    logging.info(f"Serial port {port} opened successfully.")
                    return True
                else:
                    logging.info("Serial port already open.")
                    return True
        except serial.SerialException as e:
            logging.error(f"Error opening serial port {port}: {e}")
            if i < retries - 1:
                logging.info(f"Retrying in 5 seconds...")
                time.sleep(5)
            else:
                logging.error(f"Failed to open serial port {port} after {retries} retries.")
                return False
        except Exception as e:
            logging.error(f"An unexpected error occurred while opening the serial port: {e}")
            return False
    return False

def close_serial_port():
    """Closes the serial port if it's open."""
    global serial_port
    with serial_lock:
        if serial_port and serial_port.is_open:
            serial_port.close()
            logging.info("Serial port closed.")
            serial_port = None

def send_command_and_read_response(command):
    """Sends a command to the serial port and reads the response."""
    global serial_port
    with serial_lock:
        if serial_port is None or not serial_port.is_open:
            logging.error("Serial port is not open.")
            return None

        try:
            serial_port.write(command.encode('ascii'))
            response = serial_port.readline().decode('ascii', errors='replace').strip()
            return response
        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            return None
        except Exception as e:
            logging.error(f"An unexpected error occurred during serial communication: {e}")
            return None

def get_instrument_version():
    """Retrieves the instrument model using a SCPI command."""
    command = "*IDN?\n"
    response = send_command_and_read_response(command)
    if response:
        return response
    else:
        return "N/A"

@app.route(API_ENDPOINT)
def get_all_data():
    """Retrieves all data from the data store."""
    with data_lock:
        return jsonify(data)

@app.route(API_ENDPOINT + '/<int:item_id>')
def get_data_item(item_id):
    """Retrieves a specific data item by ID."""
    with data_lock:
        item = next((item for item in data if item['id'] == item_id), None)
        if item:
            return jsonify(item)
        else:
            abort(404)

@app.route(API_ENDPOINT, methods=['POST'])
def create_data_item():
    """Creates a new data item from the request payload."""
    try:
        new_item = request.get_json()
        if not new_item or 'name' not in new_item:
            abort(400, description="Invalid JSON payload or missing 'name' field.")

        with data_lock:
            max_id = max(item['id'] for item in data) if data else 0
            new_item['id'] = max_id + 1
            new_item['done'] = False
            data.append(new_item)
            return jsonify(new_item), 201
    except KeyError as e:
        abort(400, description=f"Missing key in JSON payload: {e}")
    except Exception as e:
        logging.error(f"Error creating data item: {e}")
        abort(500, description="Internal server error.")

@app.route(API_ENDPOINT + '/<int:item_id>', methods=['PUT'])
def update_data_item(item_id):
    """Updates an existing data item by ID."""
    try:
        updated_item = request.get_json()
        if not updated_item:
            abort(400, description="Invalid JSON payload.")

        with data_lock:
            index = next((index for index, item in enumerate(data) if item['id'] == item_id), None)

            if index is None:
                abort(404)

            data[index].update(updated_item)
            return jsonify(data[index]), 200
    except KeyError as e:
        abort(400, description=f"Missing key in JSON payload: {e}")
    except Exception as e:
        logging.error(f"Error updating data item: {e}")
        abort(500, description="Internal server error.")

@app.route(API_ENDPOINT + '/<int:item_id>', methods=['DELETE'])
def delete_data_item(item_id):
    """Deletes an existing data item by ID."""
    with data_lock:
        index = next((index for index, item in enumerate(data) if item['id'] == item_id), None)
        if index is None:
            abort(404)

        del data[index]
        return Response("{}", status=204, mimetype='application/json')

@app.route('/version')
def version():
    """Retrieves the instrument model via serial or returns a default value."""
    model = get_instrument_version()
    return Response(model, mimetype='text/plain')

def main():
    """Main function to initialize and run the Flask app."""
    if not open_serial_port():
        logging.error("Failed to open serial port. Exiting.")
        sys.exit(1)

    try:
        app.run(host=FLASK_HOST, port=FLASK_PORT, debug=False)
    except Exception as e:
        logging.error(f"Flask app error: {e}")
    finally:
        close_serial_port()
        logging.info("Application finished.")

if __name__ == '__main__':
    main()

