# pulse_oximeter_reader.py
# Reads heart rate and SpO2 from a pulse oximeter via UART on Raspberry Pi.

import serial
import time

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
DATA_BITS = serial.EIGHTBITS
PARITY = serial.PARITY_NONE
STOP_BITS = serial.STOPBITS_ONE
TIMEOUT = 1

def read_pulse_oximeter_data():
    """Reads data from the pulse oximeter and prints heart rate and SpO2."""
    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, data_bits=DATA_BITS, parity=PARITY, stop_bits=STOP_BITS, timeout=TIMEOUT) as ser:
            while True:
                try:
                    line = ser.readline().decode('ascii', errors='replace').strip()
                    if line:
                        fields = line.split(',')
                        if len(fields) == 2:
                            heart_rate = fields[0]
                            spo2 = fields[1]
                            print(f'Heart Rate: {heart_rate} bpm, SpO2: {spo2} %')
                        else:
                            print(f"Warning: Invalid data format: {line}")
                except ValueError as e:
                    print(f"Error decoding data: {e}")
                except Exception as e:
                    print(f"An unexpected error occurred: {e}")
                time.sleep(1)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        print("Exiting program.")

if __name__ == "__main__":
    read_pulse_oximeter_data()

