import json
from time import sleep
from threading import Thread
from flask import Flask, Response, request, jsonify, abort
import serial

app = Flask(__name__)

# Serial port configuration for the SCPI-compatible instrument
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1

# In-memory data store for the to-do list
todo_list = [{"id": 1, "task": "Learn Flask", "done": False}, {"id": 2, "task": "Learn Serial", "done": False}]


def get_serial_connection():
    """Establishes or returns an existing serial connection."""
    global serial_connection  # Declare serial_connection as global
    try:
        if 'serial_connection' in globals() and serial_connection.is_open:
            return serial_connection
        else:
            serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=SERIAL_TIMEOUT)
            return serial_connection
    except serial.SerialException as e:
        print(f"Serial connection error: {e}")
        return None


@app.route('/version', methods=['GET'])
def get_instrument_version():
    """Retrieves the version information from the SCPI instrument."""
    serial_conn = get_serial_connection()
    if serial_conn:
        try:
            serial_conn.write(b"*IDN?\n")
            sleep(0.1)  # Allow time for the response to arrive
            response = serial_conn.readall().decode('utf-8', errors='ignore').replace('\n', '<br>')
            return Response(response, mimetype='text/html')
        except Exception as e:
            print(f"Error retrieving version: {e}")
            return Response("Error communicating with instrument.", mimetype='text/plain', status=503)
    else:
        return Response("Serial port not available.", mimetype='text/plain', status=503)


@app.route('/getdata', methods=['GET'])
def get_todo_list():
    """Retrieves the complete to-do list as JSON."""
    return jsonify(todo_list)


@app.route('/getset/<int:item_id>', methods=['GET'])
def get_todo_item(item_id):
    """Retrieves a specific to-do list item by ID."""
    item = next((item for item in todo_list if item['id'] == item_id), None)
    if item:
        return jsonify(item)
    else:
        abort(404)


@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def add_todo_item(item_id, name):
    """Adds a new to-do item via a GET request."""
    new_id = todo_list[-1]['id'] + 1 if todo_list else 1
    todo_list.append({"id": new_id, "task": name, "done": False})
    return jsonify(todo_list)


@app.route('/postjson', methods=['POST', 'GET'])
def update_todo_list():
    """Handles POST and GET requests for the to-do list."""
    if request.method == 'POST':
        if request.is_json:
            data = request.get_json()
            new_id = todo_list[-1]['id'] + 1 if todo_list else 1
            new_item = {"id": new_id, "task": data.get('task', ''), "done": data.get('done', False)}
            todo_list.append(new_item)
            return jsonify(todo_list), 201
        else:  # Handle non-JSON data (e.g., form data)
            data = request.form
            new_id = todo_list[-1]['id'] + 1 if todo_list else 1
            new_item = {"id": new_id, "task": data.get('task', ''), "done": data.get('done', False) == 'true'}
            todo_list.append(new_item)
            return jsonify(todo_list), 201
    else:  # GET request
        return jsonify(todo_list)


if __name__ == '__main__':
    try:
        app.run(debug=True, host='0.0.0.0')
    finally:
        if 'serial_connection' in globals() and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

