import serial
import time
import subprocess

# Constants for Bluetooth configuration
BLUETOOTH_DEVICE = "/dev/rfcomm4"
BLUETOOTH_BAUD_RATE = 38400
COMMAND_PREFIX = 'X'


def connect_bluetooth(device, baud):
    """Establishes a Bluetooth connection."""
    try:
        bluetooth = serial.Serial(device, baud)
        return bluetooth
    except serial.SerialException as e:
        raise RuntimeError(f"Bluetooth connection failed: {e}")


def send_command(bluetooth, command):
    """Sends a command over the Bluetooth connection."""
    try:
        full_command = (COMMAND_PREFIX + command).encode("utf-8") 
        bluetooth.write(full_command + b"\n")  # Add newline for clear message boundaries
        time.sleep(0.1)  # Add a small delay for the device to process
    except serial.SerialException as e:
        raise RuntimeError(f"Command transmission failed: {e}")


def main():
    """Main function to handle user input and send commands."""
    bluetooth = None
    try:
        # Establish Bluetooth connection
        bluetooth = connect_bluetooth(BLUETOOTH_DEVICE, BLUETOOTH_BAUD_RATE)

        while True:
            try:
                user_input = input("Enter command (or 'exit' to quit): ")
                if user_input.lower() == "exit":
                    break
                send_command(bluetooth, user_input)

            except RuntimeError as e:
                print(f"Error: {e}")
                break  # Exit on error

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if bluetooth and bluetooth.is_open:
            bluetooth.close()
            print("Bluetooth connection closed.")


if __name__ == "__main__":
    main()

